		}
	},
	[1003] = {
		unlock_by_time = "",
		name = "科尔盖档案：马尔杜克",
		unlock_by_condition_id = 1300003,
		archive_id = 1003,
		archive_icon = "TextureConfig/MardukUI/Marduk_bg_0024",
		desc = "姓名：马尔杜克\n职级：上校\n年龄：58岁\n身高：182cm\n体重：85kg\n\n<b><size=34>简历</size></b>\n科尔盖重大犯罪对策部总负责人，有丰富作战经验，任职期间科尔盖辖区犯罪率同比下降40%。\n\n<b>培训经历</b>\n2267-2270 科尔盖直属陆地治安队\n2271-2275 科尔盖重大犯罪对策部行动小队\n2275-2296 科尔盖重大犯罪对策部特别行动组\n\n<b>相关经验</b>\n2275年「雷闪行动」：在艾因索菲的肃清行动中，单人逮捕恶性武装团体首领，职级晋升为中尉。\n\n2287年「白色恐怖：0927」：在追查恫吓案「白色恐怖」过程中，迅速掌握了恐怖组织「0927」的关键线索，阻止了其轰炸西岸核心城的计划。随后马尔杜克与其小队将「0927」组织成员一网打尽，职级晋升为上尉。\n\n2287年「灭鹫计划」：科尔盖剿灭盘踞约库尔黑恶势力「鹫」的过程中，数支行动小队落入包围，伤亡惨重。马尔杜克主动申请突围战，并成功歼灭敌方指挥官，职级晋升为中校。\n\n2289年「剿灭走私网」：2289年开始与同队成员「胡狼」潜伏约库尔，调查跨原质区重大光轨走私违禁品案件，于2290年掌握关键证据后成功捉拿幕后主使，职级晋升为上校，同年成为科尔盖重大犯罪对策部管理者。\n\n2296年「▉▉▉▉」：马尔杜克率领对策部小队前往「▉▉▉」完成▉▉▉驻守任务。在任务中遭遇▉▉▉袭击，小队成员▉▉▉▉，马尔杜克行踪▉▉。\n\n————————————机密档案————————————\n\n                              权限不足，已禁止访问内容\n",
		tag_id = 2,
		archive_parameter = 0,
		archive_type = 1,
		chapter_id = {
			6010110,
			6010111
		}
	},
	[1004] = {
		unlock_by_time = "",
		name = "暗金属",
		unlock_by_condition_id = 1300004,
		archive_id = 1004,
		archive_icon = "TextureConfig/MardukUI/Marduk_bg_0024",
		desc = "迷铁之家的伊森在斯皮尔特工厂做安保时，私下偷盗了大量的智械部件及相关技术资料，并在行动时偶然发现了斯皮尔特技术部门隐藏的一份军用智械设计稿。\n\n这种军用智械在设计之初沿用了新型动力结构，并在制造过程中加入了最先进的人工智能技术，能够轻松应对各种复杂战况。其机动力已突破现有军用智械的数值天花板，军方仰仗一台的威力，即可主宰战场。\n\n智械设计的需求方案是科尔盖高层提出的，他们声称这台智械将被用作“必要时期的和平手段”。但是，斯皮尔特的技术人员在开发过程中，发现其应用标准已远超人类武器使用范畴，斯皮尔特高层心照不宣地雪藏了这份技术文档。\n\n事实上，这正是科尔盖制造的——对抗视骸的专用智械。然而产品样机交付后，科尔盖的技术部门经测试发现，完全依靠代码运行的智械极易被视骸侵蚀，遭受侵蚀后的智械将大概率变得狂躁且不可控制，甚至攻击人类。\n\n科尔盖迅速叫停了这项研究，销毁了原型机，并封存了相关资料。为降低后续智械受视骸侵染的概率，科尔盖还通过颁布技术限制法令的方式，迫使斯皮尔特工业修改生产线。后来，科尔盖发现只有持有完整人格意识的修正者，才能与视骸进行稳定的对抗，故而转向推行灰塔计划——尝试生产人造修正者。而那批拥有惊人破坏力潜能的半成品智械，渐渐被遗忘在斯皮尔特工厂的一角。\n\n但是，意外获得设计稿的伊森并不知晓这段隐秘而危险的历史，他为军用智械惊人的威力深深震撼，为再现这个奇迹，他利用先前在斯皮尔特工厂内劫掠到的智械部件，参考技术资料拼造了一台巨型智械，并沿用技术文档的名称将其命名为【暗金属】……\n",
		tag_id = 3,
		archive_parameter = 0,
		archive_type = 1,
		chapter_id = {
			6010110,
			6010111
		}
	},
	[1011301] = {
		unlock_by_time = "",
		name = "天通引擎",
		unlock_by_condition_id = 1300005,
		archive_id = 1011301,
		archive_icon = "TextureConfig/OperationDiary/OperationDiary_2001",
		desc = "虚恒作为盖亚世界生成的第一个原质区，蕴含丰富矿产，拥有高超的工业发展水平，为科尔盖的光轨设施建设提供了大量的资源支持。\n\n然而，因纪元重启，部分物理系数生成错误，虚恒地底深处生成了一种极不稳定的反重力矿物——「云歌石」。\n\n随着矿石能源产业规模的扩大，密集的工程活动让虚恒地表松动。潜藏于地底深处的「云歌石」逐渐暴露在外，不受控地向外释放能量。\n\n2278年，虚恒经历「云歌之变」，浅表岩层持续性大范围崩裂，形成四座飘浮于空的岛屿。虚恒的发展因大地的撕裂而停滞，无数家庭支离破碎。\n\n为终结云歌之变，四方院的「执明」与「烛」在虚恒上空建造了巨型重力稳定装置——「天通引擎」。\n\n「天通引擎」生成的广域能量场能够稳定「云歌石」的重力系数，为虚恒在五岛之上重建城市提供了最基础的保障。\n",
