	[41710105] = {
		unlock_by_time = "",
		name = "伯恩哈特",
		unlock_by_condition_id = 1300023,
		archive_id = 41710105,
		archive_icon = "",
		desc = "\n「上次你说要做的那个项目申请下来了吗？厉害啊……」\n\n「今天吃什么？回头搓一顿吧……」\n\n依托比尔轴监控站的分析室，毕竟是午休时间，年纪轻轻便担任分析官、高级分析官的天才们也聊着日常的闲话。但角落还有一个埋首的身影，好像感受不到周围的嘈杂，整个人都沉浸在眼前的东西上。\n\n有人拍了拍他的肩：「伯恩哈特，伯恩哈特？」\n\n「哎呦——！」\n\n伯恩哈特吓了一跳，几乎从座椅上弹了起来。他用手肘按在桌面的稿纸上，回身看到熟悉的脸孔，才松了一口气。对方也没预料到他这么大反应，不好意思地道了歉。伯恩哈特赶紧摆摆手：「没事没事，正好……我也冷静一下，好好想想。」\n\n「汤普森让我告诉你，他那个项目下午你可以去观摩，你不是一直想去吗？」\n\n「今天？呃、这个……」\n\n「有事？」\n\n拒绝别人对伯恩哈特来说大概是一件为难的事，何况这件事本来就是他自己求来的。他尴尬地张合着嘴，面色变了又变，最后还是下定决心：「嗯……手里这点东西，我想弄完再说。」\n\n「奇了。你不是天天说不能只提出问题，解决问题才是最重要的，所以才一直想去看汤普森那个项目吗？前几天去理论研究院搞合作前还一副不乐意的样子，现在又钻进去了？」\n\n「欸……想解决问题，也得先找到问题……」\n\n对方了解伯恩哈特的性格，没有多为难他，闲聊几句就走了。同事们三三两两去了食堂，只剩下零星几个人还留在自己的位子上。伯恩哈特低下了头，慢慢转回桌面前，沉默地看着手稿上的数字。\n\n「还要算下去吗？」\n\n「也只能算下去了吧……」\n\n他深吸了一口气，目光重新变得坚定起来，闷头埋回了一张张稿纸之中。\n\n",
		tag_id = 4,
		archive_parameter = 0,
		archive_type = 2,
